"""HTTP server exposing the ledger REST API using the Python standard library."""
from __future__ import annotations

import hmac
import json
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import parse_qs, unquote

from .service import LedgerService

MAX_BODY_BYTES = 1 << 20  # 1 MiB cap on request bodies

# Token-gated checkpoint-history routes. Every request to one of these is
# rejected 401 before the body is read or any state is touched unless the node
# was started with --history* and the Authorization header carries the exact
# configured bearer token.
HISTORY_ROUTES = {
    ("GET", "/v1/history/trust"),
    ("POST", "/v1/history/trust"),
    ("POST", "/v1/history/export"),
}


def build_handler(service: LedgerService) -> type[BaseHTTPRequestHandler]:
    """Create a handler class closed over the given ledger service."""

    class LedgerHandler(BaseHTTPRequestHandler):
        server_version = "VerifiableLedger/1.0"

        # -- helpers --------------------------------------------------------

        def _send_json(
            self, status: int, body: dict, sort_keys: bool = True
        ) -> None:
            data = json.dumps(
                body, ensure_ascii=False, sort_keys=sort_keys
            ).encode("utf-8")
            self.send_response(status)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            self.wfile.write(data)

        def _history_authorized(self, method: str, path: str) -> bool:
            """Bearer-token gate for the /v1/history/* routes.

            Returns True when the request may proceed. When the feature is
            disabled the gate is open (the service answers 404); otherwise a
            missing/malformed/incorrect ``Authorization: Bearer TOKEN`` header
            is answered 401 immediately, without reading the body or touching
            any state (no audit event, no file access).
            """
            if (method, path) not in HISTORY_ROUTES:
                return True
            if not getattr(service, "history_enabled", False):
                return True
            expected = (
                f"Bearer {service.history_token}"
                if service.history_token is not None
                else None
            )
            provided = self.headers.get("Authorization")
            # Compare bytes: a header containing non-ASCII (decoded latin-1 by
            # the HTTP layer) must simply mismatch, never raise out of
            # compare_digest (which rejects non-ASCII str inputs).
            if expected is None or provided is None or not hmac.compare_digest(
                provided.encode("utf-8", errors="replace"),
                expected.encode("utf-8"),
            ):
                self._send_json(
                    401,
                    {"ok": False, "error": "unauthorized"},
                    sort_keys=False,
                )
                # The body was deliberately not consumed: close the
                # connection so an unread Content-Length body cannot desync
                # the next pipelined request on a keep-alive socket.
                self.close_connection = True
                return False
            return True


        def _read_json(self) -> tuple[bool, object]:
            try:
                length = int(self.headers.get("Content-Length", "0"))
            except ValueError:
                return False, {"error": "invalid Content-Length"}
            if length <= 0:
                return False, {"error": "request body must be JSON"}
            if length > MAX_BODY_BYTES:
                return False, {"error": "request body too large"}
            raw = self.rfile.read(length)
            try:
                return True, json.loads(raw.decode("utf-8"))
            except (ValueError, UnicodeDecodeError):
                return False, {"error": "request body must be valid JSON"}

        # -- routing --------------------------------------------------------

        def do_POST(self) -> None:  # noqa: N802 (stdlib naming)
            path = self.path.split("?", 1)[0]
            # Bearer gate first: a 401 must be returned before the body is
            # read and without any state or file side effects.
            if not self._history_authorized("POST", path):
                return
            if path == "/v1/history/trust":
                # POST /v1/history/trust — append one signer certificate; the
                # success document is the contract-ordered
                # {root, records, head} log.
                ok, payload = self._read_json()
                if not ok:
                    self._send_json(
                        400, {"ok": False, "error": "input"}, sort_keys=False
                    )
                    return
                status, body = service.update_history_trust(payload)
                self._send_json(status, body, sort_keys=False)
            elif path == "/v1/history/export":
                # POST /v1/history/export — one signed page; the success
                # document has the contract key order
                # base, records, next, head, checkpoint, auth.
                ok, payload = self._read_json()
                if not ok:
                    self._send_json(
                        400, {"ok": False, "error": "input"}, sort_keys=False
                    )
                    return
                status, body = service.export_history_page(payload)
                self._send_json(status, body, sort_keys=False)
            elif path == "/v1/transactions":
                ok, payload = self._read_json()
                if not ok:
                    self._send_json(400, payload)  # type: ignore[arg-type]
                    return
                status, body = service.submit_transaction(payload)
                self._send_json(status, body)
            elif path == "/v1/forks/candidates":
                ok, payload = self._read_json()
                if not ok:
                    self._send_json(400, payload)  # type: ignore[arg-type]
                    return
                status, body = service.submit_fork_candidate(payload)
                self._send_json(status, body)
            elif path == "/v1/forks/sync/range":
                ok, payload = self._read_json()
                if not ok:
                    self._send_json(400, payload)  # type: ignore[arg-type]
                    return
                status, body = service.submit_fork_sync_range(payload)
                self._send_json(status, body)
            elif path == "/v1/forks/sync/range/attested":
                ok, payload = self._read_json()
                if not ok:
                    self._send_json(400, payload)  # type: ignore[arg-type]
                    return
                status, body = service.submit_fork_sync_range_attested(payload)
                self._send_json(status, body)
            elif path == "/v1/forks/sync/attested":
                ok, payload = self._read_json()
                if not ok:
                    self._send_json(400, payload)  # type: ignore[arg-type]
                    return
                status, body = service.submit_fork_sync_attested(payload)
                self._send_json(status, body)
            elif path == "/v1/forks/sync":
                ok, payload = self._read_json()
                if not ok:
                    self._send_json(400, payload)  # type: ignore[arg-type]
                    return
                status, body = service.submit_fork_sync(payload)
                self._send_json(status, body)
            elif path == "/v1/audit/signer/rotate":
                # POST /v1/audit/signer/rotate — rotate the Ed25519 key that
                # authenticates audit export checkpoints.
                ok, payload = self._read_json()
                if not ok:
                    self._send_json(400, payload)  # type: ignore[arg-type]
                    return
                status, body = service.rotate_audit_signer(payload)
                self._send_json(status, body)
            elif path == "/v1/trust/sources":
                # POST /v1/trust/sources — register a trusted source.
                ok, payload = self._read_json()
                if not ok:
                    self._send_json(400, payload)  # type: ignore[arg-type]
                    return
                status, body = service.register_trust_source(payload)
                self._send_json(status, body)
            elif (
                path.startswith("/v1/trust/sources/")
                and (path.endswith("/rotate") or path.endswith("/revoke"))
            ):
                # POST /v1/trust/sources/{source}/rotate | /revoke
                ok, payload = self._read_json()
                if not ok:
                    self._send_json(400, payload)  # type: ignore[arg-type]
                    return
                remainder = path[len("/v1/trust/sources/") :]
                if remainder.endswith("/rotate"):
                    source = unquote(remainder[: -len("/rotate")])
                    status, body = service.rotate_trust_source(source, payload)
                else:
                    source = unquote(remainder[: -len("/revoke")])
                    status, body = service.revoke_trust_source(source, payload)
                self._send_json(status, body)
            elif path == "/v1/trust/allowlist":
                # POST /v1/trust/allowlist — add a keyless offline-verify entry.
                ok, payload = self._read_json()
                if not ok:
                    self._send_json(400, payload)  # type: ignore[arg-type]
                    return
                status, body = service.add_allowlist_entry(payload)
                self._send_json(status, body)
            elif path.startswith("/v1/forks/") and path.endswith("/adopt"):
                # POST /v1/forks/{tip_hash}/adopt — a body is not required.
                if self.headers.get("Content-Length"):
                    self._read_json()
                tip_hash = unquote(path[len("/v1/forks/") : -len("/adopt")])
                status, body = service.adopt_fork(tip_hash)
                self._send_json(status, body)
            elif path == "/v1/blocks":
                # A body is not required; drain one if present.
                if self.headers.get("Content-Length"):
                    self._read_json()
                status, body = service.mine_block()
                self._send_json(status, body)
            elif path.startswith("/v1/blocks/"):
                remainder = path[len("/v1/blocks/") :]
                if remainder.endswith("/proofs"):
                    # POST /v1/blocks/{height}/proofs — batch Merkle proofs.
                    # The body is {"tx_ids": [...]} and is strictly validated
                    # by the service (400), before any state is read. The
                    # success document has a contract-fixed key order
                    # (height, block_hash, merkle_root, transaction_ids,
                    # proofs), so it is serialized in insertion order rather
                    # than alphabetically.
                    height = unquote(remainder[: -len("/proofs")])
                    ok, payload = self._read_json()
                    if not ok:
                        self._send_json(400, payload)  # type: ignore[arg-type]
                        return
                    status, body = service.get_proofs(height, payload)
                    self._send_json(status, body, sort_keys=False)
                else:
                    # POST /v1/blocks/{height}/confirm | /v1/blocks/{height}/rollback
                    if self.headers.get("Content-Length"):
                        self._read_json()
                    if remainder.endswith("/confirm"):
                        height = unquote(remainder[: -len("/confirm")])
                        status, body = service.confirm_block(height)
                    elif remainder.endswith("/rollback"):
                        height = unquote(remainder[: -len("/rollback")])
                        status, body = service.rollback_block(height)
                    else:
                        status, body = 404, {"error": "not found"}
                    self._send_json(status, body)
            else:
                self._send_json(404, {"error": "not found"})

        def do_DELETE(self) -> None:  # noqa: N802 (stdlib naming)
            path = self.path.split("?", 1)[0]
            if path.startswith("/v1/trust/allowlist/"):
                # DELETE /v1/trust/allowlist/{source}
                source = unquote(path[len("/v1/trust/allowlist/") :])
                status, body = service.remove_allowlist_entry(source)
                self._send_json(status, body)
            else:
                self._send_json(404, {"error": "not found"})

        def do_GET(self) -> None:  # noqa: N802 (stdlib naming)
            path, _, query = self.path.partition("?")
            # Bearer gate first; a failed gate has no side effects.
            if not self._history_authorized("GET", path):
                return
            if path == "/v1/history/trust":
                # GET /v1/history/trust — the contract-ordered
                # {root, records, head} signer log.
                status, body = service.read_history_trust()
                self._send_json(status, body, sort_keys=False)
            elif path.startswith("/v1/transactions/"):
                # GET /v1/transactions/{tx_id} — a transaction receipt; a
                # malformed or unknown tx_id returns 404.
                tx_id = unquote(path[len("/v1/transactions/") :])
                if not tx_id:
                    self._send_json(404, {"error": "transaction not found"})
                    return
                status, body = service.get_transaction(tx_id)
                self._send_json(status, body)
            elif path == "/v1/trust":
                # The trust document has a contract-fixed key order
                # (genesis_hash, sources, allowlist, audit_signers,
                # source_key_history), so it is serialized in insertion order
                # rather than alphabetically.
                status, body = service.get_trust_document()
                self._send_json(status, body, sort_keys=False)
            elif path == "/v1/audit/events":
                # GET /v1/audit/events?source=&kind=&cursor=&limit=
                params = {
                    key: values[0]
                    for key, values in parse_qs(query, keep_blank_values=True).items()
                }
                status, body = service.list_audit_events(params)
                self._send_json(status, body)
            elif path == "/v1/audit/export":
                # GET /v1/audit/export?cursor=&limit= — hash-anchored export
                # pages for offline audit verification. Repeated query
                # parameters are rejected 400 like the other strict endpoints.
                parsed = parse_qs(query, keep_blank_values=True)
                if any(len(values) > 1 for values in parsed.values()):
                    self._send_json(
                        400, {"error": "query parameters must not be repeated"}
                    )
                    return
                params = {key: values[0] for key, values in parsed.items()}
                status, body = service.export_audit_events(params)
                self._send_json(status, body)
            elif path == "/v1/chain/range":
                # GET /v1/chain/range?after_height=&after_hash=&limit=
                # Incremental canonical-chain page after an anchor. Repeated
                # query parameters are rejected 400 like the strict endpoints.
                parsed = parse_qs(query, keep_blank_values=True)
                if any(len(values) > 1 for values in parsed.values()):
                    self._send_json(
                        400, {"error": "query parameters must not be repeated"}
                    )
                    return
                params = {key: values[0] for key, values in parsed.items()}
                status, body = service.get_chain_range(params)
                self._send_json(status, body)
            elif path == "/v1/chain":
                status, body = service.get_chain()
                self._send_json(status, body)
            elif path.startswith("/v1/state/root/"):
                # GET /v1/state/root/{height} — account-state tree anchored at
                # a historical confirmed block; unknown/non-canonical/pending
                # heights are 404.
                height = unquote(path[len("/v1/state/root/") :])
                if not height:
                    self._send_json(404, {"error": "block not found"})
                    return
                status, body = service.get_state_root(height)
                self._send_json(status, body)
            elif path == "/v1/state/root":
                # GET /v1/state/root — confirmed account-state tree anchor.
                status, body = service.get_state_root()
                self._send_json(status, body)
            elif path == "/v1/forks/sync/export":
                # GET /v1/forks/sync/export?source=&request_id=&mode= —
                # export one received sync candidate. Repeated query
                # parameters are rejected 400 like the other strict
                # endpoints; the success document has a contract-fixed key
                # order, so it is serialized in insertion order.
                parsed = parse_qs(query, keep_blank_values=True)
                if any(len(values) > 1 for values in parsed.values()):
                    self._send_json(
                        400, {"error": "query parameters must not be repeated"}
                    )
                    return
                params = {key: values[0] for key, values in parsed.items()}
                status, body = service.export_fork_sync(params)
                self._send_json(status, body, sort_keys=False)
            elif path == "/v1/forks/sync/range/export":
                # GET /v1/forks/sync/range/export?source=&request_id=&mode= —
                # export one received incremental range delivery. Repeated
                # query parameters are rejected 400 like the other strict
                # endpoints; the success document has a contract-fixed key
                # order, so it is serialized in insertion order. This exact
                # match must precede the generic /v1/forks/{tip}/export
                # branch below.
                parsed = parse_qs(query, keep_blank_values=True)
                if any(len(values) > 1 for values in parsed.values()):
                    self._send_json(
                        400, {"error": "query parameters must not be repeated"}
                    )
                    return
                params = {key: values[0] for key, values in parsed.items()}
                status, body = service.export_fork_sync_range(params)
                self._send_json(status, body, sort_keys=False)
            elif path == "/v1/forks/sync/history":
                # GET /v1/forks/sync/history?source=&tip_hash=&kind=&
                # min_height=&max_height=&limit=&cursor=
                parsed = parse_qs(query, keep_blank_values=True)
                if any(len(values) > 1 for values in parsed.values()):
                    self._send_json(
                        400, {"error": "query parameters must not be repeated"}
                    )
                    return
                params = {key: values[0] for key, values in parsed.items()}
                status, body = service.list_fork_sync_history(params)
                self._send_json(status, body)
            elif path == "/v1/forks/sync":
                # GET /v1/forks/sync?source=&min_height=&max_height=&mode=&
                # limit=&cursor= — repeated query parameters are rejected 400
                # like the other strict endpoints.
                parsed = parse_qs(query, keep_blank_values=True)
                if any(len(values) > 1 for values in parsed.values()):
                    self._send_json(
                        400, {"error": "query parameters must not be repeated"}
                    )
                    return
                params = {key: values[0] for key, values in parsed.items()}
                status, body = service.list_fork_syncs(params)
                self._send_json(status, body)
            elif path == "/v1/index/transactions":
                # GET /v1/index/transactions?tx_id=&account=&height=&limit=&cursor=
                params = {
                    key: values[0]
                    for key, values in parse_qs(query, keep_blank_values=True).items()
                }
                status, body = service.list_transactions(params)
                self._send_json(status, body)
            elif path.startswith("/v1/forks/") and path.endswith("/export"):
                # GET /v1/forks/{tip_hash}/export
                tip_hash = unquote(path[len("/v1/forks/") : -len("/export")])
                status, body = service.export_fork(tip_hash)
                self._send_json(status, body)
            elif path.startswith("/v1/blocks/"):
                remainder = path[len("/v1/blocks/") :]
                if "/proof/" in remainder:
                    # GET /v1/blocks/{height}/proof/{tx_id}
                    height_raw, tx_raw = remainder.split("/proof/", 1)
                    if not height_raw or not tx_raw:
                        self._send_json(404, {"error": "not found"})
                        return
                    status, body = service.get_proof(unquote(height_raw), unquote(tx_raw))
                    self._send_json(status, body)
                elif remainder.endswith("/status"):
                    # GET /v1/blocks/{height}/status
                    height = unquote(remainder[: -len("/status")])
                    status, body = service.get_block_status(height)
                    self._send_json(status, body)
                else:
                    height = unquote(remainder)
                    status, body = service.get_block(height)
                    self._send_json(status, body)
            elif path.startswith("/v1/accounts/"):
                remainder = path[len("/v1/accounts/") :]
                if not remainder:
                    self._send_json(404, {"error": "account not found"})
                    return
                if remainder.endswith("/proof"):
                    # GET /v1/accounts/{account}/proof[?height=H]
                    encoded_account = remainder[: -len("/proof")]
                    account = unquote(encoded_account)
                    if not encoded_account or not account:
                        self._send_json(404, {"error": "account not found"})
                        return
                    # Repeated query parameters are rejected 400 like the other
                    # strict endpoints before the service sees them.
                    parsed = parse_qs(query, keep_blank_values=True)
                    if any(len(values) > 1 for values in parsed.values()):
                        self._send_json(
                            400, {"error": "query parameters must not be repeated"}
                        )
                        return
                    params = {key: values[0] for key, values in parsed.items()}
                    status, body = service.get_account_proof(account, params)
                else:
                    account = unquote(remainder)
                    status, body = service.get_account(account)
                self._send_json(status, body)
            else:
                self._send_json(404, {"error": "not found"})

    return LedgerHandler


def serve(service: LedgerService, host: str, port: int) -> ThreadingHTTPServer:
    """Create and run the HTTP server (blocks until interrupted)."""
    httpd = ThreadingHTTPServer((host, port), build_handler(service))
    httpd.serve_forever()
    return httpd

    "auth": 403,
    "state": 409,
    "io": 500,
}

@classmethod
def _history_failure(cls, result: dict) -> tuple[int, dict]:
    category = result.get("error", "io")
    return (
        cls._HISTORY_STATUS.get(category, 500),
        {"ok": False, "error": category},
    )

def _history_heads(self) -> tuple[str | None, str | None]:
    """Current (trust_head, history_head); null for a not-yet-created file.

    Caller must already hold the store lock and both file-path locks.
    Raises OSError for an ``io``-class read failure or
    ``_HistoryFileError`` for a strict-verification (``state``) defect, so
    callers can map the outcome onto the 500/409 contract.
    """
    from . import light_client

    inspection = light_client.inspect_history_files(
        self.history_path, self.history_trust_path
    )
    if not inspection.get("ok"):
        category = inspection.get("error")
        if category == "io":
            raise OSError(
                inspection.get("path"),
                "managed history file unreadable",
            )
        raise LedgerService._HistoryFileError(
            category or "state", inspection.get("path")
        )
    return inspection["trust_head"], inspection["history_head"]

class _HistoryFileError(Exception):
    """A managed history file failed strict verification mid-request."""

    def __init__(self, category: str, path: str | None) -> None:
        self.category = category
        self.path = path
        super().__init__(f"{category}: {path}")

def _append_history_access_and_save(
    self,
    action: str,
    trust_head: str | None,
    history_head: str | None,
    restore: list[tuple[str, bytes | None]] | None = None,
) -> None:
    """Append the history_access event and persist the snapshot atomically.

    The event payload has the fixed key order
    ``action, trust_head, history_head`` (a missing file contributes
    ``null``). On a snapshot failure the in-memory event is dropped and,
    when given, each ``(path, original_bytes)`` pair is restored
    best-effort; the original exception is re-raised so the caller answers
    500/io.
    """
    self.store.append_audit_event(
        EVENT_HISTORY_ACCESS,
        {
            "action": action,
            "trust_head": trust_head,
            "history_head": history_head,
        },
    )
    try:
        self.store.save()
    except BaseException:
        self.store.truncate_audit_events(1)
        if restore is not None:
            from . import light_client

            for path, original in restore:
                light_client.restore_file_bytes(path, original)
        raise

def read_history_trust(self) -> tuple[int, dict]:
    """GET /v1/history/trust — strictly read the durable signer log.

    Returns the ``{root, records, head}`` document in its contract key
    order. Every read is audited with a ``read`` history_access event; the
    event, checkpoint and generation land in one snapshot before the
    response. A missing log is ``io`` (500), a corrupt log ``state`` (409).
    """
    if not self.history_enabled:
        return 404, {"ok": False, "error": "not found"}
    from . import light_client

    with self.store.lock:
        with light_client._checkpoint_lock(
            self.history_path
        ), light_client._checkpoint_lock(self.history_trust_path):
            try:
                result = light_client.history_trust(self.history_trust_path)
                if result.get("ok") is False:
                    return self._history_failure(result)
                trust_head, history_head = self._history_heads()
                self._append_history_access_and_save(
                    "read", trust_head, history_head
                )
            except self._HistoryFileError as failure:
                return self._history_failure(
                    {"error": failure.category}
                )
            except OSError:
                return 500, {"ok": False, "error": "io"}
            except Exception:
                # Defensive HTTP boundary: any unforeseen failure is an
                # internal error; any external-file compensation already
                # ran inside _append_history_access_and_save.
                return 500, {"ok": False, "error": "io"}
            return 200, result

def update_history_trust(self, payload: object) -> tuple[int, dict]:
    """POST /v1/history/trust — append one signer-log certificate.

    The body must be a JSON object containing exactly
    ``root_seed, at, key, status``; every shape defect is 400 (input). The
    append reuses ``light_client.history_trust`` unchanged: a fresh log
    opens with ``active``, ``at`` strictly ascends, a revocation must name
    the currently active key and an identical tail is an idempotent
    no-op. A new record returns 201; the idempotent replay returns 200. The
    log write, the ``update`` history_access event and the snapshot land
    together under one shared lock; a snapshot failure restores the log's
    original bytes and drops the in-memory event, answering 500/io.
    """
    if not self.history_enabled:
        return 404, {"ok": False, "error": "not found"}
    from . import light_client

    if not isinstance(payload, dict) or set(payload) != set(
        self.HISTORY_TRUST_UPDATE_FIELDS
    ):
        return 400, {"ok": False, "error": "input"}
    at_value = payload["at"]
    if (
        isinstance(at_value, bool)
        or not isinstance(at_value, int)
        or at_value < 1
    ):
        return 400, {"ok": False, "error": "input"}

    with self.store.lock:
        with light_client._checkpoint_lock(
            self.history_path
        ), light_client._checkpoint_lock(self.history_trust_path):
            try:
                # Pre-flight: the checkpoint pair (and the trust log)
                # must strictly load before the trust log is touched, so
                # a corrupt file pair is reported (409/state or 500/io)
                # without mutating anything.
                self._history_heads()
                # Record the durable tail size before the append so a
                # byte-level change distinguishes 201 (fresh log /
                # appended record) from the 200 idempotent no-op.
                before = light_client.history_trust(self.history_trust_path)
                if before.get("ok") is False:
                    # A missing log starts a fresh one below; a corrupt or
                    # otherwise unreadable log is a state conflict and must
                    # never be touched.
                    if before.get("error") != "io":
                        return self._history_failure(before)
                    before_count = None
                else:
                    before_count = len(before["records"])
                # Snapshot the log bytes: a later snapshot failure must put
                # the already-committed external write back byte-for-byte.
                original_trust = light_client._read_bytes_or_none(
                    self.history_trust_path
                )
                result = light_client.history_trust(
                    self.history_trust_path,
                    payload["root_seed"],
                    at_value,
                    payload["key"],
                    payload["status"],
                )
                if result.get("ok") is False:
                    return self._history_failure(result)
                created = (
                    before_count is None
                    or len(result["records"]) > before_count
                )
                trust_head, history_head = self._history_heads()
                self._append_history_access_and_save(
                    "update",
                    trust_head,
                    history_head,
                    restore=[(self.history_trust_path, original_trust)],
                )
            except self._HistoryFileError as failure:
                return self._history_failure(
                    {"error": failure.category}
                )
            except OSError:
                return 500, {"ok": False, "error": "io"}
            except Exception:
                # Defensive HTTP boundary: any unforeseen failure is an
                # internal error; any external-file compensation already
                # ran inside _append_history_access_and_save.
                return 500, {"ok": False, "error": "io"}
            return (201 if created else 200), result

def export_history_page(self, payload: object) -> tuple[int, dict]:
    """POST /v1/history/export — export one signed checkpoint-history page.

    The body must be a JSON object whose keys are a subset of exactly
    ``key, after, limit`` (``key`` required; ``after``/``limit`` optional
    with the library defaults). The export reuses
    ``light_client.export_history`` unchanged — page key order,
    cursor/pagination, strict reload and the Ed25519 signature — and is
    audited with an ``export`` history_access event before responding.
    Failures map input 400 / auth 403 / state 409 / io 500.
    """
    if not self.history_enabled:
        return 404, {"ok": False, "error": "not found"}
    from . import light_client

    if not isinstance(payload, dict):
        return 400, {"ok": False, "error": "input"}
    if set(payload) - set(self.HISTORY_EXPORT_FIELDS):
        return 400, {"ok": False, "error": "input"}
    if "key" not in payload:
        return 400, {"ok": False, "error": "input"}
    after = payload.get("after")
    if after is not None and (
        isinstance(after, bool) or not isinstance(after, int) or after < 0
    ):
        return 400, {"ok": False, "error": "input"}
    limit = payload.get("limit")
    if limit is not None and (
        isinstance(limit, bool)
        or not isinstance(limit, int)
        or not (
            light_client.HISTORY_EXPORT_MIN_LIMIT
            <= limit
            <= light_client.HISTORY_EXPORT_MAX_LIMIT
        )
    ):
        return 400, {"ok": False, "error": "input"}

    with self.store.lock:
        with light_client._checkpoint_lock(
            self.history_path
        ), light_client._checkpoint_lock(self.history_trust_path):
            try:
                result = light_client.export_history(
                    self.history_path,
                    payload["key"],
                    after=after,
                    limit=(
                        limit
                        if limit is not None
                        else light_client.HISTORY_EXPORT_DEFAULT_LIMIT
                    ),
                )
                if result.get("ok") is False:
                    return self._history_failure(result)
                trust_head, history_head = self._history_heads()
                self._append_history_access_and_save(
                    "export", trust_head, history_head
                )
            except self._HistoryFileError as failure:
                return self._history_failure(
                    {"error": failure.category}
                )
            except OSError:
                return 500, {"ok": False, "error": "io"}
            except Exception:
                # Defensive HTTP boundary: any unforeseen failure is an
                # internal error; any external-file compensation already
                # ran inside _append_history_access_and_save.
                return 500, {"ok": False, "error": "io"}
            return 200, result

def _parse_persisted_audit_events(raw: object, path: str) -> list[dict]:
    """Strictly parse the append-only audit event log.

    Every event is a JSON object carrying an integer ``at`` timestamp and a
    string ``kind``; ``event_id`` values must be exactly 1..N with no gaps
    or duplicates, since the id is the event's permanent audit position
    (which also fixes the log's total ordering). Payload fields beyond
    those three are retained verbatim.

    The historical sync lifecycle events additionally have their provenance
    metadata validated: ``sync_received`` / ``sync_adopted`` /
    ``sync_expired`` must carry a non-empty ``source`` and ``request_id``
    and a 64-char lowercase hex ``tip_hash``; an ``expires_at`` and the
    frozen tip summary (``height`` / ``length`` / ``status``) are checked
    when present — older snapshots' adopted events predate those fields, so
    missing ones are accepted but malformed ones are corruption. The
    keyless-allowlist events ``allowlist_added`` / ``allowlist_removed``
    likewise require a non-empty ``source`` and an integer
    ``expires_at``.
    """
    if raw is None:
        return []
    if not isinstance(raw, list):
        raise StateRecoveryError(path, "'audit_events' must be a list")
    sync_kinds = {
        EVENT_SYNC_RECEIVED,
        EVENT_SYNC_ADOPTED,
        EVENT_SYNC_EXPIRED,
    }
    allowlist_kinds = {
        EVENT_ALLOWLIST_ADDED,
        EVENT_ALLOWLIST_REMOVED,
    }
    # The node-managed checkpoint-history endpoints append history_access
    # events carrying the action and the heads the two external files had
    # at access time (64-hex, or null when the file did not exist yet).
    history_access_kinds = {EVENT_HISTORY_ACCESS}
    events: list[dict] = []
    for i, event in enumerate(raw):
        if not isinstance(event, dict):
            raise StateRecoveryError(path, f"audit event {i + 1} must be an object")
        event_id = event.get("event_id")
        kind = event.get("kind")
        at = event.get("at")
        if (
            isinstance(event_id, bool)
            or not isinstance(event_id, int)
            or event_id != i + 1
        ):
            raise StateRecoveryError(
                path,
                f"audit event at position {i} has event_id {event_id!r}, "
                f"expected {i + 1}",
            )
        if not isinstance(kind, str) or not kind:
            raise StateRecoveryError(path, f"audit event {event_id} needs a kind")
        if isinstance(at, bool) or not isinstance(at, (int, float)):
            raise StateRecoveryError(path, f"audit event {event_id} needs a numeric 'at'")
        if kind in sync_kinds:
            source = event.get("source")
            request_id = event.get("request_id")
            tip_hash = event.get("tip_hash")
            if not isinstance(source, str) or not source:
                raise StateRecoveryError(
                    path, f"audit event {event_id} ({kind}) needs a source"
                )
            if not isinstance(request_id, str) or not request_id:
                raise StateRecoveryError(
                    path, f"audit event {event_id} ({kind}) needs a request_id"
                )
            if not crypto.is_hex64(tip_hash):
                raise StateRecoveryError(
                    path, f"audit event {event_id} ({kind}) has an invalid tip_hash"
                )
            expires_at = event.get("expires_at")
            if expires_at is not None and (
                isinstance(expires_at, bool) or not isinstance(expires_at, int)
            ):
                raise StateRecoveryError(
                    path,
                    f"audit event {event_id} ({kind}) expires_at must be an integer",
                )
            height = event.get("height")
            if height is not None and (
                isinstance(height, bool) or not isinstance(height, int) or height < 0
            ):
                raise StateRecoveryError(
                    path, f"audit event {event_id} ({kind}) has an invalid height"
                )
            length = event.get("length")
            if length is not None and (
                isinstance(length, bool) or not isinstance(length, int) or length < 1
            ):
                raise StateRecoveryError(
                    path, f"audit event {event_id} ({kind}) has an invalid length"
                )
            status = event.get("status")
            if status is not None and status not in (
                STATUS_PENDING,
                STATUS_CONFIRMED,
            ):
                raise StateRecoveryError(
                    path, f"audit event {event_id} ({kind}) has invalid status"
                )
            # The three frozen summary fields travel together: a partially
            # frozen event is an inconsistent write and is corruption.
            summary_fields = (height, length, status)
            if any(field is not None for field in summary_fields) and any(
                field is None for field in summary_fields
            ):
                raise StateRecoveryError(
                    path,
                    f"audit event {event_id} ({kind}) has a partial frozen summary",
                )
            # The attested-sync feature adds an optional mode; when present
            # it must be a recognized delivery mode.
            mode = event.get("mode")
            if mode is not None and mode not in (
                SYNC_MODE_PLAIN,
                SYNC_MODE_ATTESTED,
            ):
                raise StateRecoveryError(
                    path, f"audit event {event_id} ({kind}) has invalid mode"
                )
        elif kind in allowlist_kinds:
            # The keyless allowlist is authoritative configuration (exactly
            # like trust_sources): an allowlist_added/removed event must
            # carry a non-empty ``source`` and a plain (non-boolean)
            # integer ``expires_at``. A malformed payload is snapshot
            # corruption and fails recovery rather than loading.
            source = event.get("source")
            expires_at = event.get("expires_at")
            if not isinstance(source, str) or not source:
                raise StateRecoveryError(
                    path, f"audit event {event_id} ({kind}) needs a source"
                )
            if isinstance(expires_at, bool) or not isinstance(expires_at, int):
                raise StateRecoveryError(
                    path,
                    f"audit event {event_id} ({kind}) expires_at must be an integer",
                )
        elif kind in history_access_kinds:
            # history_access events bind the audit log to the node-managed
            # checkpoint-history files: action is read/update/export and
            # both heads must be present as either 64-char lowercase hex
            # or JSON null (the referenced file did not exist yet).
            action = event.get("action")
            if action not in ("read", "update", "export"):
                raise StateRecoveryError(
                    path,
                    f"audit event {event_id} ({kind}) has an invalid action",
                )
            for head_field in ("trust_head", "history_head"):
                if head_field not in event:
                    raise StateRecoveryError(
                        path,
                        f"audit event {event_id} ({kind}) is missing "
                        f"{head_field}",
                    )
                head = event[head_field]
                if head is not None and not crypto.is_hex64(head):
                    raise StateRecoveryError(
                        path,
                        f"audit event {event_id} ({kind}) {head_field} "
                        "must be 64 lowercase hex characters or null",
                    )
        events.append(dict(event))
    return events

